"""
Generate an entirely synthetic repeated-measures dataset for open-science teaching.
Seed: 20261013
No real participant-level data are used.
"""
import pandas as pd
import numpy as np
from pathlib import Path

OUT = Path(".")
rng = np.random.default_rng(20261013)
participants = []
for group, prefix in [("HC", "HC"), ("FM", "FM")]:
    for i in range(1, 21):
        pid = f"{prefix}{i:03d}"
        age = int(np.clip(np.round(rng.normal(40, 8)), 25, 55))
        education = int(rng.choice([1, 2, 3, 4], p=[.08, .28, .27, .37]))
        duration = round(float(np.clip(rng.lognormal(2.45, .55), .5, 25)), 1) if group == "FM" else np.nan
        participants.append(dict(participant_id=pid, group=group, age_years=age,
            education_level=education, pain_duration_years=duration,
            fm_diagnosis="yes" if group == "FM" else "no",
            symptom_trait=rng.normal(), cognition_trait=rng.normal()))
demo = pd.DataFrame(participants)
rows = []
for _, p in demo.iterrows():
    fm = p.group == "FM"
    isi_base = (10 if fm else 5) + 3*p.symptom_trait + rng.normal(0, 2)
    phq_base = (7 if fm else 3) + 2.3*p.symptom_trait + rng.normal(0, 1.5)
    pcs_base = (22 if fm else 5) + 6*p.symptom_trait + rng.normal(0, 4)
    pain_base = (4.4 if fm else .15) + p.symptom_trait + rng.normal(0, .7)
    for week in range(1, 9):
        missed = rng.random() < (.075 if fm else .055)
        wave = np.sin((week + rng.normal(0, .2))*np.pi/4)
        isi = int(np.clip(round(isi_base + .55*wave + rng.normal(0, 2.2)), 0, 28))
        phq = int(np.clip(round(phq_base + .35*wave + rng.normal(0, 1.6)), 0, 27))
        pcs = int(np.clip(round(pcs_base + .45*wave + rng.normal(0, 3)), 0, 52))
        if fm:
            current = float(np.clip(pain_base + .5*wave + rng.normal(0, 1.1), 0, 10))
            least = float(np.clip(current - abs(rng.normal(1.4, .8)), 0, 10))
            worst = float(np.clip(current + abs(rng.normal(2, 1)), 0, 10))
        else:
            current = float(np.clip(abs(rng.normal(.15, .25)), 0, 1.2))
            least = float(np.clip(abs(rng.normal(.05, .15)), 0, .7))
            worst = float(np.clip(abs(rng.normal(.3, .35)), 0, 1.8))
        symptom_load = (isi/28)*.30 + (phq/27)*.25 + (pcs/52)*.15
        stroop_rt = max(250, 760 + (150 if fm else 0) + 55*symptom_load - 30*p.cognition_trait + rng.normal(0,55))
        go_rt = max(180, 420 + (35 if fm else 0) + 25*symptom_load - 18*p.cognition_trait + rng.normal(0,28))
        stroop_correct = int(np.clip(round(57 - 1.5*symptom_load + .6*p.cognition_trait + rng.normal(0,1.3)),48,60))
        go_correct = int(np.clip(round(77 - 1.5*symptom_load + .8*p.cognition_trait + rng.normal(0,1.4)),65,80))
        nogo_correct = int(np.clip(round(18.5 - .5*symptom_load + .7*p.cognition_trait + rng.normal(0,1.2)),12,20))
        vals = dict(
            isi_total=isi, phq9_total=phq, pcs_total=pcs,
            current_pain_0_10=round(current,1), least_pain_past_week_0_10=round(least,1),
            worst_pain_past_week_0_10=round(worst,1), stroop_mean_rt_ms=round(stroop_rt,1),
            stroop_correct_n=stroop_correct, stroop_incorrect_n=60-stroop_correct,
            gonogo_go_mean_rt_ms=round(go_rt,1), gonogo_go_correct_n=go_correct,
            gonogo_go_incorrect_n=80-go_correct, gonogo_nogo_correct_rejections_n=nogo_correct,
            gonogo_nogo_commission_errors_n=20-nogo_correct)
        if missed:
            vals = {k: np.nan for k in vals}
        else:
            for k in vals:
                if rng.random() < .012:
                    vals[k] = np.nan
        rows.append(dict(participant_id=p.participant_id, group=p.group, week=week,
            visit_completed=int(not missed), age_years=p.age_years,
            education_level=p.education_level, pain_duration_years=p.pain_duration_years,
            fm_diagnosis=p.fm_diagnosis, **vals))
df = pd.DataFrame(rows).sort_values(["participant_id","week"]).reset_index(drop=True)
df.loc[df.participant_id.eq("HC007"), "education_level"] = 5
df.loc[df.participant_id.eq("FM012") & df.week.eq(3), "current_pain_0_10"] = 11.0
df.loc[df.participant_id.eq("FM004") & df.week.eq(6), "stroop_mean_rt_ms"] = 89.0
df.to_csv(OUT / "synthetic_fibromyalgia_weekly_dataset.csv", index=False)
demo.drop(columns=["symptom_trait","cognition_trait"]).to_csv(OUT / "synthetic_fibromyalgia_participant_demographics.csv", index=False)
